              "binding": "vars.start.output.category"
            },
            {
              "id": "reason",
              "label": "Reason (required if rejecting)",
              "type": "string",
              "direction": "output",
              "variable": "vars.reason",
              "required": false
            }
          ],
          "outcomes": [
            { "id": "approve", "name": "Approve", "type": "string", "isPrimary": true, "action": "Continue" },
            { "id": "reject", "name": "Reject", "type": "string", "isPrimary": false, "action": "Continue" }
          ]
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "reason": { "type": "string" },
            "Action": { "type": "string", "enum": ["Approve", "Reject"], "default": "Approve" }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "logDecision1",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": {
        "label": "Log Decision"
      },
      "inputs": {
        "script": "const decision = $vars.hitlReview1.status;\nconst reason = $vars.hitlReview1.output.reason || null;\nreturn {\n  expenseId: $vars.start.output.expenseId,\n  submitter: $vars.start.output.submitter,\n  category: $vars.start.output.category,\n  amount: $vars.start.output.amount,\n  decision: decision,\n  reason: reason\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "end1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End"
      },
      "inputs": {},
      "outputs": {
        "approvalLog": {
          "source": "=js:$vars.logDecision1.output"
        }
      }
    }
  ],
  "edges": [
    {
      "id": "edge-start-hitlReview1",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "hitlReview1",
      "targetPort": "input"
    },
    {
      "id": "edge-hitlReview1-logDecision1",
      "sourceNodeId": "hitlReview1",
      "sourcePort": "completed",
      "targetNodeId": "logDecision1",
      "targetPort": "input"
    },
    {
      "id": "edge-logDecision1-end1",
      "sourceNodeId": "logDecision1",
      "sourcePort": "success",
      "targetNodeId": "end1",
      "targetPort": "input"
    }
  ],
  "definitions": [
    {
      "nodeType": "core.trigger.manual",
      "version": "1.0",
      "category": "trigger",
      "description": "Start the process manually",
      "tags": [
        "trigger",
        "start",
        "manual"
      ],
      "sortOrder": 80,
      "display": {
        "label": "Manual trigger",
        "icon": "play",
        "shape": "circle"
      },
      "handleConfiguration": [
        {
          "position": "right",
          "handles": [
            {
              "id": "output",
              "type": "source",
              "handleType": "output",
              "showButton": true,
              "constraints": {
                "forbiddenTargetCategories": [
                  "trigger"
                ]
              }
            }
          ],
          "visible": true
        }
      ],
